/**
 * Browser-half chat node renderer for the `media` kind: renders the node's
 * video/audio asset as a native, controllable player.
 * @module dsh-media-player/client/media-node
 */

import type { PropsLocale, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'

const mediaStyle: React.CSSProperties = {
  display: 'block',
  maxWidth: '100%',
  maxHeight: 480,
  borderRadius: 12,
  border: '1px solid var(--dsw-alias-border-l2-darkmode-thin)',
}

const rootStyle: React.CSSProperties = {
  margin: '6px 0',
}

/** Render one media chat node as an inline video or audio player. */
export function MediaChatNodeView({ node }: PropsRuntime<'conversation.chat.node', 'media'> & PropsLocale<'media-player'>) {
  const data = node.data
  const isVideo = data.mimeType.startsWith('video/')
  return (
    <div style={rootStyle} data-dsh-plugin="media-player" data-dsh-part="media">
      {data.title !== undefined && data.title.length > 0 ? (
        <div data-dsh-part="title">{data.title}</div>
      ) : null}
      {isVideo ? (
        <video style={mediaStyle} src={data.url} controls preload="metadata" data-dsh-part="video" />
      ) : (
        <audio style={mediaStyle} src={data.url} controls preload="metadata" data-dsh-part="audio" />
      )}
    </div>
  )
}
